"""复核工作区页面布局；仅使用现有报告与受限缩略图引用。"""
import html,re

def enhance(page,data):
 page=re.sub(r'<p class="notice">.*?</p>','<p class="notice">先核对主体，再点选鸟种。点选后照片位置保持；快速复核可自动下一张。未定位到鸟体不等于没有鸟，候选仍需人工判断。</p>',page,count=1,flags=re.S)
 page=page.replace('鸟类图库 · 连拍分组与相似折叠','鸟类照片 · 快速复核')
 start=page.index('<div class="controls"><h2>点选鸟种');end=page.index('<div class="controls"><h2>拍摄背景',start)
 progress='''<div class="controls review-progress"><p id="review-message" role="status"></p><button id="export-review" class="primary" type="button">导出复核备份</button><details><summary>导入已有复核记录</summary><label>选择复核 JSON<input id="import-review" type="file" accept=".json,application/json"></label><button id="apply-import" type="button" disabled>应用导入复核记录</button></details><small>选择会暂存在当前浏览器；建议定期导出备份。换浏览器时可导入继续。</small></div>'''
 page=page[:start]+progress+page[end:]
 start=page.index('<div class="controls"><h2>拍摄背景');end=page.index('<div class="controls"><h2>浏览与筛选',start)
 background=page[start:end].replace('<div class="controls"><h2>拍摄背景</h2>','<details class="controls background-settings"><summary>拍摄背景与候选依据</summary>',1)
 background=background.rsplit('</div>',1)[0]+'</details>'
 page=page[:start]+background+page[end:]
 start=page.index('<div class="controls"><h2>浏览与筛选');end=page.index('<div class="controls"><h2>整组确认',start)
 filters='''<div class="controls"><div class="fields"><label>拍摄目录<select id="folder-filter"><option value="">全部目录</option></select></label><label>复核状态<select id="review-filter"><option value="all">全部（不含已剔除）</option><option value="pending">待复核（含不确定）</option><option value="confirmed">已人工确认</option><option value="no_bird">无鸟 · 已剔除</option><option value="any">所有照片（含已剔除）</option><option value="uncertain">暂不确定</option><option value="none_match">候选都不对</option><option value="undetected">未定位到主体</option></select></label><label>鸟名或文件名<input id="library-search" type="text" placeholder="中文名、旧名、学名、文件名"></label></div><p id="library-summary" role="status"></p><details><summary>分组、相似折叠与浏览设置</summary><label>连拍最大间隔（秒）<input id="burst-gap" type="number" min="1" max="120" value="30"></label><p><label><input id="group-bursts" type="checkbox" checked>同种鸟连续照片分组</label><label><input id="fold-similar" type="checkbox" checked>折叠非常相似的照片</label></p><button id="apply-view" type="button">应用浏览设置</button><button id="reset-view" type="button">恢复自动分组与封面</button><button id="export-view" type="button">导出浏览设置</button><label>恢复浏览设置 JSON<input id="import-view" type="file" accept=".json,application/json"></label><button id="apply-view-import" type="button" disabled>应用浏览设置文件</button><p>相似照片可展开；人工标记无鸟的照片可从“已剔除”恢复。两者均保留原文件。推测同种需要复核，不代表同一只鸟。</p></details><p id="view-message" role="status"></p></div>'''
 page=page[:start]+filters+page[end:]
 start=page.index('<div class="controls"><h2>整组确认</h2>');end=page.index('<div id="library-groups">',start)
 toolbar='''<div id="review-toolbar" class="review-toolbar"><button id="start-quick" class="primary" type="button">开始快速复核</button><button id="refresh-groups" type="button">更新筛选与分组</button><button id="undo-review" type="button" disabled>撤销刚才</button><span id="workspace-message" role="status">点选后保留当前位置，按需更新分组。</span></div><div id="quick-review" hidden><div class="quick-toolbar"><button id="quick-prev" type="button">← 上一张</button><button id="quick-next" type="button">下一张 →</button><button id="quick-no-bird" type="button">0 无鸟，剔除</button><button id="quick-uncertain" type="button">U 暂不确定</button><button id="quick-undo" type="button">撤销并返回</button><button id="exit-quick" type="button">返回分组浏览</button><label class="inline"><input id="auto-next" type="checkbox" checked>确认后自动下一张</label><p id="quick-progress" role="status"></p><small>1–5 确认候选；0 无鸟；U 不确定；← → 换图；Z 撤销。输入鸟名时快捷键停用。</small></div><div id="quick-stage"></div></div>'''
 page=page[:start]+toolbar+page[end:]
 start=page.index('<section class="photo-card"');end=page.index('</div><script id="review-data"',start)
 cards=[]
 for i,row in enumerate(data['rows']):
  view=row['views'][0];thumb=html.escape(view['thumbnail']['name'],quote=True)
  candidates=''.join(f'<div class="compare"><div><h4>纯图像候选</h4><ol id="raw-{i}-{j}"></ol></div><div><h4>地区与时间辅助</h4><ol id="adjusted-{i}-{j}"></ol></div></div><p id="change-{i}-{j}"></p>' for j,_ in enumerate(row['views']))
  cards.append(f'''<section class="photo-card" id="photo-{i}" tabindex="-1"><h2>{html.escape(row['path'])}</h2><div class="review-layout"><figure><img loading="lazy" src="review-thumbnails/{thumb}" alt="供用户复核的受限主体或整图缩略图"><figcaption>{html.escape(row.get('detection',{}).get('message',''))}</figcaption></figure><div class="review-actions"><div id="selected-{i}" role="status"></div><p>点一个鸟种即可确认；详细候选内可追加同图其他鸟种。</p><div id="quick-choices-{i}" class="quick-choices"></div><p id="taxon-note-{i}" class="taxon-note"></p><button id="no_bird-{i}" type="button">无鸟，剔除</button><button id="uncertain-{i}" type="button">暂不确定</button><button id="none_match-{i}" type="button">候选都不对</button><button id="unreviewed-{i}" type="button">清除选择／恢复</button><button id="undo-photo-{i}" type="button">撤销刚才</button><button id="next-photo-{i}" type="button">继续下一张待复核</button><details><summary>搜索其他鸟种</summary><input id="species-search-{i}" type="text" placeholder="中文名、旧名或学名"><select id="species-results-{i}"><option value="">先搜索鸟种</option></select><button id="add-species-{i}" type="button">确认搜索鸟种</button></details></div></div><details class="candidate-detail"><summary>候选依据、拍摄信息与多鸟选择</summary><p id="context-{i}"></p>{candidates}<p>原有真值：{html.escape(str(row.get('truth') or '未知'))}；人工确认单独保存。</p></details><details><summary>封面与相似折叠设置</summary><button id="cover-{i}" type="button">设为本组封面</button><button id="keep-{i}" type="button">保留此图显示</button></details></section>''')
 page=page[:start]+''.join(cards)+page[end:]
 css='''.review-progress details{display:inline-block;margin:0 16px}.review-progress small{display:block}.background-settings{margin:12px 0}.review-layout{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,1fr);gap:24px}.review-layout figure{margin:0}.review-layout img{height:440px;max-height:65vh;background:#edf2ef}.review-layout figcaption,.taxon-note{font-size:13px;color:#62716a}.quick-choices{display:grid;gap:8px}.quick-choices button{margin:0;text-align:left;font-weight:600}.quick-choices button[aria-pressed=true]{background:#285d50;color:white}.review-toolbar,.quick-toolbar{position:sticky;top:0;z-index:20;background:#f3f8f5;border:1px solid #bfcfc6;padding:8px 14px;border-radius:10px}.quick-toolbar{position:static}.review-toolbar button,.quick-toolbar button{margin-top:0}.inline{display:inline-block}.group-confirm{position:sticky;top:calc(var(--review-toolbar-height,64px) + 8px);z-index:10;background:#eef6f2;padding:12px;border-radius:8px;margin:12px 0}.group-confirm select{display:inline-block;max-width:100%}.group-confirm p{font-size:14px}#quick-review{background:#f3f8f5}#workspace-message{font-size:14px}#quick-progress{font-weight:600}.photo-card h2{font-size:18px;overflow-wrap:anywhere}.review-actions details{margin-top:12px}.candidate-detail{margin-top:12px}@media(max-width:850px){.review-layout{grid-template-columns:1fr}.review-layout img{height:340px}.review-toolbar{position:static}.group-confirm{top:0}}'''
 return page.replace('</style>',css+'</style>',1)
